import java.util.List;

/**
 * The item-specific risk surcharges the MHPCO levies on the items of a quote.
 *
 * <p>Knows which risks an item can carry and what each costs, and holds the
 * MHPCO's reading of the scope question: an item-specific surcharge is a
 * percentage of the base premium of the affected item, not of the policy base
 * premium. The surcharges of a quote are therefore the sum over its items.
 *
 * <p>Changes whenever the MHPCO recognises a new insurable risk or revises a
 * risk rate; knows nothing about the policy-wide modifiers (loyalty, first
 * insurance, follow-up contract), which apply to the policy base premium.
 */
final class RiskSurcharges {

    private static final int CURSE_SURCHARGE_PERCENT = 50;
    private static final int HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
    private static final int HIGH_ENCHANTMENT_FROM = 5;
    private static final int PERCENT = 100;

    private RiskSurcharges() {
    }

    static int of(List<Item> items) {
        return items.stream().mapToInt(RiskSurcharges::surchargesOn).sum();
    }

    private static int surchargesOn(Item item) {
        return curseSurchargeOn(item) + highEnchantmentSurchargeOn(item);
    }

    private static int highEnchantmentSurchargeOn(Item item) {
        if (item.enchantment() < HIGH_ENCHANTMENT_FROM) {
            return 0;
        }
        return percentOfBasePremium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
    }

    private static int curseSurchargeOn(Item item) {
        if (!item.cursed()) {
            return 0;
        }
        return percentOfBasePremium(item, CURSE_SURCHARGE_PERCENT);
    }

    private static int percentOfBasePremium(Item item, int percent) {
        return PriceList.basePremiumFor(item) * percent / PERCENT;
    }
}
