import com.fasterxml.jackson.databind.JsonNode;
import java.util.ArrayList;
import java.util.List;

/**
 * Translates between the MHPCO wire format and the domain.
 *
 * <p>Changes whenever the JSON schema of a scenario or of a results document
 * changes; knows nothing about tariffs, premiums or the command line.
 */
final class ScenarioJson {

    private ScenarioJson() {
    }

    static List<Item> itemsOfFirstQuote(JsonNode scenario) {
        return itemsOf(scenario.get("steps").get(0));
    }

    private static List<Item> itemsOf(JsonNode quoteStep) {
        List<Item> items = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            items.add(new Item(item.get("type").asText(), item.path("enchantment").asInt(),
                    item.path("cursed").asBoolean()));
        }
        return items;
    }

    static String quoteResults(int premium) {
        return "{\"results\":[{\"premium\":" + premium + "}]}";
    }
}

